namespace CheckoutPricing.Domain;

public sealed class ShippingFeePolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public int FeeCents(int payableTotalCents, LoyaltyTier tier, bool express) =>
        express ? ExpressFeeCents(tier) : StandardFeeCents(payableTotalCents, tier);

    private static int ExpressFeeCents(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents();

    private static int ExpressFeeCents() => ShippingFeePolicy.ExpressFeeCentsValue;

    private static int StandardFeeCents(int payableTotalCents, LoyaltyTier tier) =>
        tier >= LoyaltyTier.Gold || payableTotalCents >= FreeStandardFromCents ? 0 : StandardFeeCentsValue;

    private const int ExpressFeeCentsValue = ExpressFeeCents_;
    private const int StandardFeeCentsValue = StandardFeeCents_;
}
EOF

