namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    private const int CapCents = 2_000;
    private const int MinimumSubtotalCents = 3_000;
    private const int WelcomeFiveCents = 500;
    private const int SummerTenCapCents = 1_500;

    public int DiscountCents(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyPart = LoyaltyPartCents(subtotalCents, tier);
        var promoPart = PromoPartCents(subtotalCents - loyaltyPart, promoCode);
        return Math.Min(subtotalCents, loyaltyPart + promoPart);
    }

    public int LoyaltyPartCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(CapCents, subtotalCents * RatePercent(tier) / 100);

    private static int PromoPartCents(int remainingCents, string? promoCode) =>
        promoCode?.ToUpperInvariant() switch
        {
            "WELCOME5" => WelcomeFiveCents,
            "SUMMER10" => Math.Min(SummerTenCapCents, remainingCents / 10),
            _ => 0
        };

    private static int RatePercent(LoyaltyTier tier) =>
        tier switch
        {
            LoyaltyTier.Bronze => 5,
            LoyaltyTier.Silver => 10,
            LoyaltyTier.Gold => 15,
            LoyaltyTier.Platinum => 20,
            _ => 0
        };
}
